// VYAS ASTRA — C++ engine test bench.
//
// Compares the C++ port against golden vectors produced by the Python engine
// (cpp/tests/golden_vectors.h, generated by cpp/tools/gen_golden.py).  The
// Python engine is itself validated against the Swiss Ephemeris, so a match
// here means both engines agree with the reference astronomy.
#include <cmath>
#include <cstdio>
#include <string>

#include "astro.hpp"
#include "ephemeris.hpp"
#include "golden_vectors.h"

namespace {

int g_failures = 0;
int g_checks = 0;

void check(bool ok, const std::string& what) {
    ++g_checks;
    if (!ok) {
        ++g_failures;
        std::printf("  FAIL  %s\n", what.c_str());
    }
}

void check_close(double got, double want, double tol, const std::string& what) {
    ++g_checks;
    const double diff = std::fabs(got - want);
    if (diff > tol) {
        ++g_failures;
        std::printf("  FAIL  %s: got %.9f want %.9f (diff %.3e)\n",
                    what.c_str(), got, want, diff);
    }
}

}  // namespace

int main(int argc, char** argv) {
    const std::string kernel = argc > 1 ? argv[1] : "data/de440s.bsp";
    std::printf("VYAS C++ engine test bench\n");
    std::printf("kernel: %s\n", kernel.c_str());

    // ---- 1. Julian day -----------------------------------------------------
    // 2000-01-01 12:00 UTC is JD 2451545.0 by definition.
    check_close(vyas::julian_day_utc(2000, 1, 1, 12.0), 2451545.0, 1e-9, "JD J2000");
    // 1990-05-15 09:05 UTC (the Jaipur golden case).
    check_close(vyas::julian_day_utc(1990, 5, 15, 9.0 + 5.0 / 60.0), 2448026.8784722, 1e-6,
                "JD 1990-05-15 09:05");

    // ---- 2. Ayanamsa vs Swiss Ephemeris -----------------------------------
    check_close(vyas::ayanamsa::lahiri_deg(2451545.0), 23.8531709167, 1.0 / 3600.0,
                "Lahiri ayanamsa at J2000 (1 arcsec)");
    check_close(vyas::ayanamsa::lahiri_deg(2435553.5), 23.2455251667, 1.0 / 3600.0,
                "Lahiri ayanamsa 1956-03-21 (1 arcsec)");

    // ---- 3. Full chart comparison -----------------------------------------
    vyas::Ephemeris eph(kernel);
    const char* names[9] = {"Sun", "Moon", "Mars", "Mercury", "Jupiter",
                            "Venus", "Saturn", "Rahu", "Ketu"};
    const int naif[7] = {vyas::NAIF_SUN, vyas::NAIF_MOON, vyas::NAIF_MARS_BARY,
                         vyas::NAIF_MERCURY_BARY, vyas::NAIF_JUPITER_BARY,
                         vyas::NAIF_VENUS_BARY, vyas::NAIF_SATURN_BARY};

    for (const auto& c : vyas::golden::kCases) {
        std::printf("\ncase %s (%04d-%02d-%02d %02d:%02d tz %+.1f)\n", c.label.c_str(),
                    c.year, c.month, c.day, c.hour, c.minute, c.tz_hours);
        const double jd_ut = vyas::julian_day_utc(c.year, c.month, c.day,
                                                  c.hour + c.minute / 60.0 - c.tz_hours);
        const double jd_tt = vyas::julian_day_tt_full(jd_ut);

        check_close(vyas::ayanamsa::lahiri_deg(jd_tt), c.ayanamsa, 1e-6, "ayanamsa");
        check_close(eph.ascendant_sidereal(jd_ut, c.latitude, c.lon_east),
                    c.ascendant, 1e-4, "ascendant (0.36 arcsec)");

        for (int i = 0; i < 7; ++i) {
            const vyas::BodyPosition p = eph.graha(naif[i], jd_tt);
            check_close(p.longitude, c.lon[static_cast<std::size_t>(i)], 2e-3,
                        std::string(names[i]) + " longitude");
            check_close(p.speed, c.speed[static_cast<std::size_t>(i)], 2e-3,
                        std::string(names[i]) + " speed");
        }
        const vyas::BodyPosition rahu = eph.node(/*mean=*/true, jd_tt);
        check_close(rahu.longitude, c.lon[7], 1e-6, "Rahu longitude");
        check_close(rahu.speed, c.speed[7], 1e-6, "Rahu speed");
        check_close(vyas::norm360(rahu.longitude + 180.0), c.lon[8], 1e-6, "Ketu longitude");
    }

    std::printf("\n%d checks, %d failures\n", g_checks, g_failures);
    return g_failures == 0 ? 0 : 1;
}
